INSERT INTO `menu_item` VALUES (17,'Yam Fries',3000.00,'41','Tasty yam cut in thick strips and lightly salted','Yam-Fries.jpg',7,100,'','Active'),(18,'Sweet Potato Fries',3000.00,'41','Delicious deep fried sweet potatoes chips cut in strips and lightly salted ','WhatsApp Image 2023-01-27 at 15.58.58.jpeg',8,97,'','Active'),(21,'Moët & Chandon Brut',75000.00,'22','Lively and generous, Brut Imperial distinguishes itself by a bright fruitiness, a seductive palate and an elegant maturity, that continually seduce and delight. The colour is an elegant golden straw yellow with green highlights.','Snip20230123_96.png',0,NULL,NULL,'Active'),(22,'Moët & Chandon Rosé',95000.00,'22','AN EXPRESSIVE PALATE COMBINING INTENSITY AND SUPPLENESS. The juicy, persistent intensity of berries (strawberry, raspberry, redcurrant) The fleshiness and firmness of peach. The freshness of a subtle note of menthol.','Snip20230123_97.png',0,NULL,NULL,'Active'),(23,'Martini Prosecco',25000.00,'22','Prosecco is a light-bodied, vibrant, fresh, highly aromatic and crisp wine. It has a medium to high amount of acidity and large, frothy bubbles. Dominant flavours typically include apple, honeysuckle, peach, melon and pear. Secondary flavours can include cream, hazelnut and tropical fruits.','Snip20230123_98.png',2,NULL,NULL,'Active'),(24,'Bature Brewery - Harmattan Haze (6%)',2650.00,'17','Inspired by the Hazy Harmattan days sent down from the Sahel desert, this juicy, hazy beer keeps you fresh. The most stylish IPA in West Africa! More flavour, more hops and more juiciness!','BB-HH.png',3,100,'','Active'),(25,'South African Cider ?? (Bottle)',2500.00,'17','Savanna Dry or Hunters (depending on availability at the time of purchase). ','Snip20230130_17.png',1,32,'','Active'),(27,'Bature Brewery - Lagos Lager (4.5%)',2650.00,'17','Your Lagos, Your Lager. Light and refreshing, Lagos Lager is the only beer for the city. Brewed with the highest quality barley, this crisp, refreshing lager is a tribute to the founding of Bature craft brewery in Victoria Island, Lagos. A craft lager with mandarin hop aromas and chewy malty taste.','BB-LL.png',4,95,'','Active'),(28,'Bature Brewery - Black Gold Stout (8%)',2650.00,'17','Black Gold is a new icon, the best stout in Africa, made in Nigeria! Our African Cup and World Beer Award winning Stout brewed with Nigerian coffee and malts. This is a strong, delicious and unique stout.\r\n\r\nMade with freshly ground dark roast coffee from Taraba and Plateau, sorghum from the south and west of Nigeria adds a subtle sweetness to balance out this bold stout.','BB-BG.png',4,100,'','Active'),(34,'Chicken Nuggets and Fries (MM)',0.00,'25','Homemade chicken nuggets with fries','Chicken Nuggets and Fries.jpeg',1,88,'','Active'),(35,'Jara Special Chicken & Jollof (MM)',0.00,'25','Fried chicken and jollof rice with plantain','Chicken and jollof - MM.jpeg',2,93,'','Active'),(47,'White Rice',2500.00,'12','Steamed long grain rice','White rice Bowl.jpeg',0,NULL,'','Inactive'),(49,'Ground Nuts',500.00,'26','Small Bowl','Ground-Nuts.jpeg',0,NULL,NULL,'Active'),(52,'Plantain Chips',500.00,'26','Small Bowl','Snip20230202_17.png',0,65,'','Active'),(53,'Chin Chin ',500.00,'26','Small Bowl','WhatsApp Image 2023-02-02 at 13.26.43.jpeg',0,NULL,NULL,'Active'),(67,'Rock Shandy',4000.00,'18','Soda water, lemonade, bitters and fresh lemon combine beautifully in a refreshing, low-alcohol rock shandy.','Rock-Shandy24.jpg',1,98,'','Active'),(69,'Chapman',4000.00,'18','Nigeria’s favourite non-alcoholic cocktail.','Chapman24.jpg',2,89,'','Active'),(70,'Sweet Ginger Beer',4000.00,'18','Refreshing, sparkling, slightly sweet & spicy','Sweet-Ging.jpg',1,95,'','Active'),(72,'Zobo Sunrise ',4000.00,'15','Refreshing, healthy with a naughty kick of tequila','WhatsApp Image 2023-01-28 at 15.36.11.jpeg',4,NULL,NULL,'Inactive'),(73,'Spicy Pineapple Margarita',6000.00,'15','This mouthwatering Spicy Pineapple Margarita is the perfect celebration sipper.','WhatsApp Image 2023-01-30 at 13.14.02.jpeg',0,94,'','Inactive'),(74,'Spiced Mojito',4000.00,'15','The Spiced Mojito - a cool, crisp, summery blend of rum, mint, lime and soda.','WhatsApp Image 2023-01-30 at 14.18.51.jpeg',4,NULL,NULL,'Inactive'),(77,'Coffee / Espresso (Single)',2000.00,'27','Single shot of Jollof\'s finest beans','WhatsApp Image 2023-01-31 at 14.38.57.jpeg',0,NULL,NULL,'Active'),(78,'Coffee / Espresso (Double)',3000.00,'27','A double shot of Jollof\'s finest beans','WhatsApp Image 2023-01-31 at 14.38.57.jpeg',0,NULL,NULL,'Active'),(79,'Coffee / Cappucino',3000.00,'27','A cappuccino is the perfect balance of espresso, steamed milk and foam. This coffee is all about the structure and the even splitting of all elements into equal thirds. ','WhatsApp Image 2023-01-31 at 14.57.04.jpeg',0,NULL,NULL,'Active'),(80,'Coffee / Latte',3000.00,'27','A latte or caffè latte is a milk coffee that is a made up of one or two shots of espresso, steamed milk and a final, thin layer of frothed milk on top.','Snip20230128_55.png',0,NULL,NULL,'Active'),(81,'Coffee / Americano',2500.00,'27','The key to an Americano is that it starts with espresso and adopts the flavours and aromas of the espresso, but with a less powerful taste.','WhatsApp Image 2023-01-31 at 14.57.04.jpeg',0,NULL,NULL,'Active'),(82,'Hot Chocolate',2000.00,'27','Hot! Hot!\r\nOoh, we got it!\r\nHot! Hot!\r\nHey, we got it!\r\nHot! Hot!\r\nSay, we got it!\r\nHot chocolate!','Snip20230202_23.png',0,NULL,NULL,'Active'),(83,'Tea / English Breakfast',2000.00,'27','Full-bodied, robust, rich and blended to go well with milk and sugar, in a style traditionally associated with a hearty English breakfast','',7,NULL,NULL,'Active'),(84,'Tea / Green Tea',2000.00,'27','Green tea is considered to have originated in China. It is said that even today the word “tea” in China refers only to green tea, not to the general category of tea as it does in the West. ','',6,NULL,NULL,'Active'),(85,'Schweppes - Zobo',1200.00,'19','','zobo2.jpg',10,100,'','Active'),(86,'Schweppes - Soda Water',1200.00,'19','','soda2.jpg',12,97,'','Active'),(87,'Schweppes - Tonic',1200.00,'19','','tonic.jpg',11,99,'','Active'),(88,'Schweppes - Bitter Lemon',1200.00,'19','','bitter-lemon2.jpg',9,88,'','Active'),(89,'Schweppes - Ginger',1200.00,'19','','ginger.jpg',8,100,'','Active'),(90,'Coke Zero',1200.00,'19','','Coke-Zero2.jpg',7,100,'','Active'),(91,'Coke',1200.00,'19','','Coke2.jpg',6,94,'','Active'),(92,'Ribena Pack - Blackcurrant ',800.00,'19','','blackcurrant.jpeg',15,NULL,NULL,'Active'),(93,'Ribena Pack -  Strawberry',800.00,'19','','strawberry.jpeg',16,NULL,NULL,'Active'),(100,'RED - Malbec-Syrah | Arrogant Frog',20000.00,'16','Aromas of sweet spices and violets with fresh blueberry flavours. Full bodied with mellow velvety tannins, liquorice and blackcurrant flavours and a long finish.','AF-Malbec.jpeg',2,NULL,NULL,'Active'),(101,'RED - Pinot-Noir | Arrogant Frog',20000.00,'16','Light colour typical of France, meaning you can see through the glass as you drink the bottle. Pleasant aromatics full of wild strawberries and red cherries. Lifted acidity typical of Pinot Noir freshens the pallet, even if the medium bodied wine has a richness that appeals to even the heaviest of red wine lovers.','AF-PN.jpeg',2,NULL,NULL,'Active'),(102,'WHITE - Chardonnay | Arrogant Frog',20000.00,'16','This bright golden yellow Chardonnay is a mellow, elegant wine with pineapple and nutty flavours and hints of lime blossom. Its tropical style and smooth, soft texture make for a relaxing drink that pairs magnificently with light meats and fish.','AF-Chard.jpeg',1,NULL,NULL,'Active'),(103,'ROSE - Semi Sweet | Berol',20000.00,'16','Fine rose wine with a smooth entry that then opens being very fruity with flavours of raspberry of good persistence. The end is clear and pleasant.','Berol-Rose-SS.jpeg',3,NULL,NULL,'Active'),(104,'WHITE - Macabeo | Berol',20000.00,'16','Premium semi-sweet fine Spanish wine. Marques de Berol, Corella-Navarra, Spain: Clean white wine, transparent, bright with greenish tones. On the nose, this elegant wine has a white fruit aroma, frank and medium persistence. ','Berol-Macabeo.jpeg',1,NULL,NULL,'Active'),(105,'RED -  Petit Verdot | Berol',22500.00,'16','Medium bodied with velvet texture, high alcohol, ample tannins and notes of black chokeberry, black currant, black wild cherry, prune and dried herbs on the palate.','Berol-Petit-Verdot.jpeg',2,NULL,NULL,'Active'),(107,'WHISKY / Pogues ?? / Shot',2500.00,'28','A single shot, as standard. Add your mixer from the Soft Drinks section.','pogues.png',0,NULL,NULL,'Active'),(114,'Semo',1500.00,'41','Swallow','Semo-24.jpg',6,100,'','Active'),(138,'Martini Rose Demi-Sec',25000.00,'22','Perfect for an al fresco meal or aperitif, the vibrant fruit notes of this wine can be elevated by the saltiness and acidity of seafood dishes.','Snip20230125_123.png',2,NULL,NULL,'Active'),(139,'RED - Sweet Red | B&G Cuvee Speciale',12000.00,'16','This french wine is delightful and invigorating with lush flavours of red fruits giving it a strong fruity taste yet well balanced on the palate.','Snip20230125_124.png',1,NULL,NULL,'Inactive'),(140,'Laurent-Perrier Brut',60000.00,'22','Laurent Perrier Champagne is an elegant Champagne, composed of a blend of the finest Chardonnay, Pinot and Pinot Meunier grapes. … Crisp, fresh and elegant, Brut L-P reflects the fundamental essence of our Champagnes. The color is a pale golden hue, with fine and persistent bubbles.','Snip20230125_2.png',0,NULL,NULL,'Active'),(142,'The Chocolate Block',50000.00,'16','A wine which reflects the rich Mediterranean climate well suited for making wines; The Chocolate Block is a flawlessly beautiful wine with bold, complex notes of berries, dark chocolate and liquorice.','Snip20230125_3.png',3,2,'','Active'),(143,'Non-Alcoholic Wine - Light Live Chardonnay',15000.00,'19','Bottle. Produced in the best Italian and Spanish vineyards, LIGHT live CHARDONNAY is White wine Chardonnay without alcohol.','Snip20230125_4.png',0,NULL,'5,6','Active'),(144,'Non-Alcoholic Wine - Light Live Cabernet Sauvignon',15000.00,'19','Bottle. Light Live Cabernet Sauvignon is a non-alcoholic wine with a characteristic deep red colour and the fresh fruity aroma of cherry.\r\n','Snip20230125_5.png',2,NULL,NULL,'Active'),(145,'Takeaway Pack (x1)',500.00,'34','Takeaway Pack to go','Snip20230125_9.png',1,180,'','Active'),(158,'Eva Water',1500.00,'19','Eva Water Bottle','WhatsApp Image 2023-02-01 at 09.34.18.jpeg',17,15,'','Active'),(167,'WHISKY / Claymore ??????? / Shot ',2500.00,'28','A single shot, as standard. Add your mixer from the Soft Drinks section.','claymore.png',2,42,NULL,'Active'),(168,'RUM / Dead Man\'s Finger Spiced / Shot ',2500.00,'28','A single shot, as standard. Add your mixer from the Soft Drinks section.','deadman.png',4,49,NULL,'Active'),(169,'VODKA / Eristoff ?? / Shot',2500.00,'28','A single shot, as standard. Add your mixer from the Soft Drinks section.','eristoff.png',4,50,NULL,'Active'),(170,'WHISKEY / Jack Daniel\'s No.7 ?? / Shot',3000.00,'28','A single shot, as standard. Add your mixer from the Soft Drinks section.','JD7.png',3,50,NULL,'Active'),(171,'TEQUILA / Camino ?? / Shot',2000.00,'28','A single shot (white or gold depending on availability at the time of purchase), as standard.','camino.png',6,8,NULL,'Active'),(173,'VODKA / NEFT ?? (100ml)',6000.00,'28','Individual NEFT can - 100ml - that\'s 4 shots baby!','WhatsApp Image 2023-02-03 at 13.30.18.jpeg',5,6,NULL,'Active'),(175,'Vanilla Ice Cream',0.00,'24','2 x Scoops of Vanilla Ice-Cream\r\n\r\nSelect sauce options, if required','Snip20230203_82.png',5,91,'23,41','Active'),(179,'Sprite',1200.00,'19','Small Bottle','Sprite-Can.jpeg',13,99,'','Active'),(184,'Glass of House White Wine',4000.00,'16','Glass House White White. State your preference of Sweet or Dry in SABIS.','Snip20230211_259.png',0,100,'35,36','Active'),(185,'Glass of House Red Wine',4000.00,'16','Glass House Red Wine. State your preference of S